SubProceso Normalizar(a Como Entero Por Referencia, b Como Entero Por Referencia)
    Definir auxiliar Como Entero;
    Si a > b Entonces
        auxiliar <- a;
        a <- b;
        b <- auxiliar;
    FinSi
FinSubProceso

Proceso EjecutarNormalizacion
    Definir n1 Como Entero;
    Definir n2 Como Entero;
    Leer n1;
    Leer n2;
    Normalizar(n1, n2);
    Escribir n1;
    Escribir n2;
FinProceso

